<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserUidVO;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserUidAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserUidAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserUidAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getUid returns null on a freshly created holder.
         */
        public function testUidNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserUidAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isUidAssigned());
            $this->assertNull($holder->getUid());
        }
}
class ImplWithUserUidAttributeHolderUnitTest
{
  use UserUidAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUidRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUid();
    }}
